contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint min, uint d, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(address(this).balance >= d);
        c.SetMinSum(min); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint before = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert((before >= min && before >= am) ? (c.balances(address(this)) + am == before) : (c.balances(address(this)) == before));
    }
    receive() external payable {}
    fallback() external payable {}
}

