pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 min, uint256 d, uint256 am) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d);
        try c.SetMinSum(min) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        uint256 before;
        try c.balances(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        try c.Collect(am) {} catch { return; }
        assertTrue((before >= min && before >= am) ? (c.balances(address(this)) + am == before) : (c.balances(address(this)) == before));
    }

    function testFuzz_run(uint256 min, uint256 d, uint256 am) public {
        _run(min, d, am);
    }

    receive() external payable {}

    fallback() external payable {}
}
